# Code generated by Claude
"""Tests of src/sequential_policy.py with made-up stages (no simulation).

    python experiments/sequential_policy_test.py

Checks, with a navigation-like stage that finishes after 3 steps and a manipulation-like stage that never does: the next stage steps on the tick AFTER
the first reports done; the status (stage, phase inherited from the earlier stage, handoff, error and the failing stage's outcome name); observe
runs for every stage up to the current one; a finished stage's restore holds back the current stage until it is finished; resume reaches the stages up
to the current one; the reports are nested by stage name with the top-level stage's keys also at the top; invalid arguments are rejected.
"""

import os
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

from src.sequential_policy import make_hold_stage, make_request_operator_stage, make_sequential_policy  # noqa: E402

results = []


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}")


def make_stages(log, fail_at=None):
    nav = {"n": 0, "restore_ticks": 0, "restoring": False}

    def nav_step(obs):
        nav["n"] += 1
        log.append(("nav", obs["tick"]))
        return [{"mode": "base", "twist": (0.1, 0.0)}]

    def nav_restore(obs):
        if not nav["restoring"]:
            return None
        nav["restore_ticks"] += 1
        return ([{"mode": "pedestal", "height": 0.0}], nav["restore_ticks"] >= 3)

    stage_nav = {"name": "NAV", "step": nav_step, "done": lambda: nav["n"] >= 3, "phase": lambda: "ARRIVED" if nav["n"] >= 3 else "GO",
                 "error": lambda: "stuck" if fail_at is not None and nav["n"] >= fail_at else None, "failure_outcome": "NAV_FAILED",
                 "observe": lambda obs: log.append(("observe", obs["tick"])), "restore": nav_restore,
                 "resume": lambda: log.append(("nav resume",)), "report": lambda: {"nav_steps": nav["n"]}, "report_top_level": True}
    manip = {"name": "MANIP", "step": lambda obs: (log.append(("manip", obs["tick"])), None)[1], "resume": lambda: log.append(("manip resume",)),
             "report": lambda: {"grasped": False}}
    return nav, [stage_nav, manip]


def main():
    log = []
    nav, stages = make_stages(log)
    ctx = {}
    pol = make_sequential_policy(stages, handoff_after=0, ctx=ctx)
    check("the shared context is the one passed in", pol["ctx"] is ctx)
    st0 = pol["status"]()
    check("status at the start: first stage, its phase, no handoff", st0 == {"stage": "NAV", "phase": "GO", "handoff": False, "error": None}, str(st0))
    for tick in range(3):
        pol["step"]({"tick": tick})
    check("the first stage stepped 3 times and nothing else did", [e for e in log if e[0] in ("nav", "manip")] == [("nav", 0), ("nav", 1), ("nav", 2)])
    st = pol["status"]()
    check("once the first stage is done the status already names the second stage, inherits the first's last phase and says handoff",
          st == {"stage": "MANIP", "phase": "ARRIVED", "handoff": True, "error": None}, str(st))
    pol["step"]({"tick": 3})
    check("the second stage steps on the tick AFTER the first reported done", log[-2:] == [("observe", 3), ("manip", 3)], str(log[-2:]))
    check("observe runs for the finished first stage every tick", [e for e in log if e[0] == "observe"] == [("observe", t) for t in range(4)])
    nav["restoring"] = True
    out1 = pol["step"]({"tick": 4})
    out2 = pol["step"]({"tick": 5})
    out3 = pol["step"]({"tick": 6})
    check("while a finished stage restores, the current stage is held back (its commands are sent instead)", out1 and out1[0]["mode"] == "pedestal"
          and out2 and out2[0]["mode"] == "pedestal" and ("manip", 4) not in log and ("manip", 5) not in log)
    check("the tick the restore finishes, the current stage steps in the same call", ("manip", 6) in log and out3 is None)
    nav["restoring"] = False
    log.clear()
    pol["resume"]()
    check("resume reaches the stages up to and including the current one", log == [("nav resume",), ("manip resume",)], str(log))
    rep = pol["report"]()
    check("the report is nested by stage and the top-level stage's keys are also at the top",
          rep == {"nav_steps": 3, "stages": {"NAV": {"nav_steps": 3}, "MANIP": {"grasped": False}}}, str(rep))

    log2 = []
    nav2, stages2 = make_stages(log2, fail_at=2)
    pol2 = make_sequential_policy(stages2, handoff_after=0)
    pol2["step"]({"tick": 0})
    pol2["step"]({"tick": 1})
    st = pol2["status"]()
    check("a failing stage: error and the stage's own outcome name in the status", st["error"] == "stuck" and st["failure_outcome"] == "NAV_FAILED", str(st))
    pol3 = make_sequential_policy([make_hold_stage()], handoff_after=None)
    check("no handoff stage: the clock starts at once", pol3["status"]()["handoff"] is True)
    s = make_request_operator_stage("why")
    check("the request stage asks once, then holds", s["step"]({}) == {"mode": "request_teleop", "reason": "why"} and s["step"]({}) is None)
    for bad in ({"stages": [], "handoff_after": 0}, {"stages": [make_hold_stage()], "handoff_after": 1}):
        try:
            make_sequential_policy(**bad)
            check(f"rejects {bad['handoff_after']} with {len(bad['stages'])} stages", False)
        except ValueError:
            check(f"rejects {bad['handoff_after']} with {len(bad['stages'])} stages", True)
    print(f"\n{sum(results)}/{len(results)} checks passed")
    sys.exit(0 if all(results) else 1)


if __name__ == "__main__":
    main()
